function applyCoupon<C extends string>(available: C[], code: C): string {
  return available.includes(code) ? `Applied ${code}` : `Unknown coupon ${code}`;
}

function createMachine<S extends string>(config: { states: S[]; initial: S }) {
  return { states: config.states, initial: config.initial };
}

function formatPrice(cents: number | number[]): string | string[] {
  return Array.isArray(cents) ? cents.map(toDollars) : toDollars(cents);
}

function toDollars(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

