function applyCoupon<C extends string>(available: C[], code: NoInfer<C>): string {
  return available.includes(code) ? `Applied ${code}` : `Unknown coupon ${code}`;
}

function createMachine<S extends string>(config: { states: S[]; initial: NoInfer<S> }) {
  return { states: config.states, initial: config.initial };
}

function formatPrice(cents: number): string;
function formatPrice(cents: number[]): string[];
function formatPrice(cents: number | number[]): string | string[] {
  return Array.isArray(cents) ? cents.map(toDollars) : toDollars(cents);
}

function toDollars(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

// ---- Type tests (do not edit) ----
applyCoupon(['WELCOME10', 'LOYAL5'], 'LOYAL5');
// @ts-expect-error: 'WELCOM10' is a typo, not an available coupon
applyCoupon(['WELCOME10', 'LOYAL5'], 'WELCOM10');

const machine = createMachine({ states: ['cart', 'shipping', 'payment'], initial: 'cart' });
type T1 = Expect<Equal<typeof machine.initial, 'cart' | 'shipping' | 'payment'>>;
// @ts-expect-error: 'checkout' is not one of the declared states
createMachine({ states: ['cart', 'shipping', 'payment'], initial: 'checkout' });

const one = formatPrice(4500);
const many = formatPrice([4500, 1299]);
type T2 = Expect<Equal<typeof one, string>>;
type T3 = Expect<Equal<typeof many, string[]>>;

console.log(applyCoupon(['WELCOME10'], 'WELCOME10'), machine.initial, one, many);
